/**
 * Shell — nptoy chrome: a thin config of the kit's AppShell (top bar, /command
 * bar, \ drawer, ? shortcuts, tab hotkeys). Generated by new-service.mjs; edit
 * TABS / status / labels here, fill the pages under src/pages/.
 */
import { useState, useEffect, useRef } from 'react'
import { AppShell, useLang, Avatar } from 'lilak-ui'
import { get, portalProfile, portalHome } from '../api'
import { communityApi } from '../community_api'
import { ENABLED_THEMES } from '../theme/main'
import SettingsPage from '../pages/SettingsPage'
import FilesTab from '../g4/FilesTab.jsx'
import GeometryTab from '../g4/GeometryTab.jsx'
import InputsTab from '../g4/InputsTab.jsx'
import SimulationTab from '../g4/SimulationTab.jsx'
import Community from './Community.jsx'

const TABS = [
  { id: "setup", icon: "home" },
  { id: "geometry", icon: "shapes" },
  { id: "simulation", icon: "spinner" },
  { id: "files", icon: "folder" },
  { id: "community", icon: "community" },
  { id: "set", icon: "settings" },
]

// Simulation-session status shown in the top bar. Maps the backend session state
// (Geant4/nptool lifecycle) to a label + a dot colour readable on the orange bar.
const STATUS = {
  none:  { text: '대기',         dot: 'rgba(255,255,255,0.55)' },  // no live session
  boot:  { text: 'initializing', dot: '#ffe0b0' },                // start → G4 building geometry/physics
  init:  { text: 'initialized',  dot: '#ffe0b0' },                // ready at Idle>
  run:   { text: 'running',      dot: '#8ef0a6' },                // /run/beamOn in progress
  ended: { text: 'ended',        dot: '#bcd7ff' },                // a run finished (ready again)
  stop:  { text: 'stopped',      dot: '#ffb3ab' },                // session process gone
}
// `ever` = a session existed this page-view. User-stop removes the session (so
// /api/session returns null) — if one had existed, that null means "stopped",
// otherwise it's the initial "대기".
function statusKey(sess, ever) {
  if (!sess) return ever ? 'stop' : 'none'
  if (sess.state === 'starting') return 'boot'
  if (sess.state === 'running') return 'run'
  if (sess.state === 'stopped') return 'stop'
  if (sess.state === 'idle') return sess.runs > 0 ? 'ended' : 'init'
  return 'none'
}

export default function Shell() {
  const { t, lang } = useLang()
  const [me, setMe] = useState(portalProfile())   // refreshed from portal DB via /api/whoami
  const [tab, setTab] = useState("setup")
  // Top-level tab layout: code default (TABS) overridden by the saved /api/layout
  // (order/labels/icons/hidden), editable from the Settings 탭 + portal Manage UI.
  // Only the tab STRIP is config-driven — each tab's in-tab rail stays code (PAGES).
  const [layout, setLayout] = useState({ tabs: TABS })
  const [sess, setSess] = useState(null)      // live simulation session (polled)
  const [proj, setProj] = useState({ name: '', run: null })  // setup name + next run number
  const [notifs, setNotifs] = useState([])    // @mention notifications (shown in the \ drawer)
  const everRef = useRef(false)               // a session has existed this page-view

  useEffect(() => {
    let alive = true
    const tick = async () => {
      try {
        const d = await get('/api/session')
        if (!alive) return
        if (d.session) everRef.current = true
        setSess(d.session)
      } catch { if (alive) setSess(null) }
    }
    tick()
    const id = setInterval(tick, 1000)
    return () => { alive = false; clearInterval(id) }
  }, [])

  useEffect(() => {
    let alive = true
    const load = () => get('/api/whoami')
      .then((d) => {
        if (!alive) return
        setMe({
          name: d.name || d.username || d.email || 'guest',
          username: d.username || '',
          email: d.email || '',
          role: d.role || 'user',
          color: d.color || '',
          shape: d.shape || '',
        })
      })
      .catch(() => {})
    load()
    const id = setInterval(load, 10000)
    return () => { alive = false; clearInterval(id) }
  }, [])

  // Watch the user's batch jobs (always, regardless of the open tab/panel) and post a
  // system message the moment one finishes — 시뮬레이션 배치가 끝나면 알림. Diff each
  // poll's statuses; fire on the transition INTO a terminal state (not on first load,
  // so already-finished jobs stay quiet).
  const jobStatusRef = useRef(null)   // Map<id, status>; null until the first poll
  useEffect(() => {
    let alive = true
    const TERM = ['done', 'failed', 'timeout', 'cancelled']
    const tick = async () => {
      let d
      try { d = await get('/api/jobs') } catch { return }
      if (!alive) return
      const jobs = d.jobs || []
      const prev = jobStatusRef.current
      if (prev) {
        for (const j of jobs) {
          const was = prev.get(j.id)
          if (was && was !== j.status && TERM.includes(j.status) && !TERM.includes(was)) {
            const ev = j.params && j.params.n_events
            const name = j.run_name ? j.run_name + '.root' : '배치 결과'
            const mb = Math.round((j.size_bytes || 0) / 1024 / 1024 * 10) / 10
            const text = j.status === 'done'
              ? `배치 완료: ${name}${ev ? ` · ${ev.toLocaleString()} 이벤트` : ''}${mb ? ` · ${mb} MB` : ''}`
              : j.status === 'timeout' ? `배치 시간초과: ${name}`
              : j.status === 'cancelled' ? `배치 취소됨: ${name}`
              : `배치 실패: ${name}${j.error ? ' — ' + j.error : ''}`
            window.dispatchEvent(new CustomEvent('nptoy-notify',
              { detail: { text, level: j.status === 'done' ? 'info' : 'error' } }))
          }
        }
      }
      jobStatusRef.current = new Map(jobs.map((j) => [j.id, j.status]))
    }
    tick()
    const id = setInterval(tick, 3000)
    return () => { alive = false; clearInterval(id) }
  }, [])

  // Poll @mention notifications for the \ drawer.
  const loadNotifs = () => communityApi.notifications().then(setNotifs).catch(() => {})
  useEffect(() => {
    loadNotifs()
    const id = setInterval(loadNotifs, 10000)
    return () => clearInterval(id)
  }, [])
  const openNotif = (n) => {
    setTab('community')
    communityApi.deleteNotification(n.id).then(loadNotifs).catch(() => {})
  }

  // ── app status notifications: transient top-right toasts, also logged to the drawer.
  //    Any component fires window CustomEvent('nptoy-notify', { detail: { text } }). ──
  const APP_NOTES_KEY = 'nptoy-app-notes'
  const [toasts, setToasts] = useState([])
  const [appNotes, setAppNotes] = useState(() => {
    try { return JSON.parse(localStorage.getItem(APP_NOTES_KEY) || '[]') } catch { return [] }
  })
  const noteSeq = useRef(0)
  const persistNotes = (list) => { try { localStorage.setItem(APP_NOTES_KEY, JSON.stringify(list)) } catch {} }
  useEffect(() => {
    const onNote = (e) => {
      const text = e.detail && e.detail.text
      if (!text) return
      const level = (e.detail && e.detail.level) || 'info'
      const id = 'n' + (++noteSeq.current) + '_' + Date.now()
      setToasts((t) => [...t, { id, text, level }])
      // errors linger longer so they aren't missed
      setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), level === 'error' ? 6500 : 3600)
      setAppNotes((prev) => { const next = [{ id, text, level, ts: new Date().toISOString() }, ...prev].slice(0, 50); persistNotes(next); return next })
    }
    window.addEventListener('nptoy-notify', onNote)
    return () => window.removeEventListener('nptoy-notify', onNote)
  }, [])
  const delAppNote = (id) => setAppNotes((prev) => { const next = prev.filter((n) => n.id !== id); persistNotes(next); return next })
  const clearAllNotes = () => {
    setAppNotes([]); persistNotes([])
    communityApi.clearNotifications().then(loadNotifs).catch(() => {})
  }

  // Merge @mention notifications + app status messages, newest first.
  const mergedNotes = [
    ...notifs.map((n) => ({ key: 'c' + n.id, ts: n.created_at || '', title: `@${n.from_name} 님이 멘션했습니다`,
      body: n.body, onClick: () => openNotif(n) })),
    ...appNotes.map((n) => ({ key: n.id, ts: n.ts, title: n.text, body: '', level: n.level, onDel: () => delAppNote(n.id) })),
  ].sort((a, b) => (a.ts < b.ts ? 1 : -1))

  const notifNode = mergedNotes.length ? (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
      {mergedNotes.map((n) => (
        <div key={n.key} onClick={n.onClick}
          style={{ position: 'relative', textAlign: 'left', border: '1px solid var(--nav-border)', background: 'var(--nav-accent)',
            color: 'var(--nav-text)', borderRadius: 8, padding: '8px 10px', cursor: n.onClick ? 'pointer' : 'default',
            borderLeft: n.level === 'error' ? '3px solid #dc2626' : undefined,
            display: 'flex', flexDirection: 'column', gap: 2 }}>
          <span style={{ fontSize: 'var(--fs-small, 12px)', fontWeight: 600, paddingRight: 16 }}>{n.title}</span>
          {n.body && <span style={{ fontSize: 'var(--fs-tiny, 11px)', color: 'var(--nav-text-muted)', overflow: 'hidden',
            textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{n.body}</span>}
          {n.onDel && <button onClick={(e) => { e.stopPropagation(); n.onDel() }} title="지우기"
            style={{ position: 'absolute', top: 4, right: 6, border: 'none', background: 'transparent',
              color: 'var(--nav-text-muted)', cursor: 'pointer', fontSize: 13, lineHeight: 1 }}>×</button>}
        </div>
      ))}
      <button onClick={clearAllNotes}
        style={{ alignSelf: 'flex-start', marginTop: 2, border: 'none', background: 'transparent',
          color: 'var(--nav-text-muted)', cursor: 'pointer', fontSize: 'var(--fs-tiny, 11px)' }}>모두 지우기</button>
    </div>
  ) : null

  // Command mode: pressing Esc while typing in a field blurs it, so the global
  // tab keys ([ ]) and each tab's number-key menu shortcuts take over — the same
  // "type → Esc → command mode" flow across every tab.
  useEffect(() => {
    const onKey = (e) => {
      if (e.key !== 'Escape') return
      const el = document.activeElement
      const tag = el && el.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (el && el.isContentEditable)) {
        el.blur()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  // Load the saved tab layout (falls back to the code default on error).
  useEffect(() => {
    get('/api/layout').then((l) => { if (l && Array.isArray(l.tabs) && l.tabs.length) setLayout(l) }).catch(() => {})
  }, [])

  // If the active tab got hidden/removed in the layout, fall back to the first visible.
  useEffect(() => {
    const vis = (layout.tabs || TABS).filter((tb) => !tb.hidden)
    if (vis.length && !vis.some((tb) => tb.id === tab)) setTab(vis[0].id)
  }, [layout]) // eslint-disable-line react-hooks/exhaustive-deps

  const visible = (layout.tabs || TABS).filter((tb) => !tb.hidden)
  const tabs = visible.map((tb) => ({ id: tb.id, label: tb.label || t('tab_' + tb.id), icon: tb.icon }))

  const st = STATUS[statusKey(sess, everRef.current)]
  // During a live session show its actual run number; otherwise the next run # that
  // a new run would use. Output files are {project}_{run}.{user}.sim.root.
  const runNo = sess?.run ?? proj.run
  const status = (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10, fontSize: 'var(--fs-tiny, 11px)', color: 'var(--nav-text)' }}>
      {proj.name && <span style={{ fontWeight: 600 }}>{proj.name}</span>}
      {runNo != null && <span style={{ fontFamily: 'var(--font-mono)', opacity: 0.8 }}>#{runNo}</span>}
      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontFamily: 'var(--font-mono)' }}>
        <span style={{ width: 6, height: 6, borderRadius: '50%', backgroundColor: st.dot }} />
        {st.text}
      </span>
    </span>
  )

  const labels = {
    help: t('cmd_help'), system: t('nav_system'), theme: t('set_theme'), language: t('set_lang'),
    account: t('nav_account'), notifications: t('notif_title'), command: t('cmd_placeholder'), shortcuts: t('shortcuts_title'),
  }

  const PAGES = {
    setup: <InputsTab onSetupName={setProj} />,
    geometry: <GeometryTab active={tab === 'geometry'} />,
    simulation: <SimulationTab />,
    files: <FilesTab active={tab === 'files'} />,
    community: <Community role={me.role} onOpenFiles={() => setTab('files')} active={tab === 'community'}
      menuConfig={(layout.tabs || []).find((x) => x.id === 'community')?.codeMenu} />,
    set: <SettingsPage menuConfig={(layout.tabs || []).find((x) => x.id === 'set')?.codeMenu} />,
  }

  return (
    <>
      <AppShell
        brand={lang === 'ko' ? t('brand') : 'lilak'}
        service={t('svc_name')}
        tabs={tabs}
        active={tab}
        onTab={setTab}
        themes={ENABLED_THEMES}
        status={status}
        labels={labels}
        notifications={notifNode}
        commandBar={false}
        accountName={me.name}
        accountMeta={me.email}
        accountIcon={false}   /* top bar shows the id only (no avatar) */
        accountAvatar={<Avatar icon={me.shape} color={me.color} seed={me.username || me.email || me.name} size={46} />}
        onExit={() => { window.location.href = portalHome() }}
        exitLabel={t('exit_portal')}
      >
        {/* Keep every visible tab mounted (display toggle) so page state survives switches.
            PAGES is keyed by tab id (the in-tab rails live inside those pages); a tab
            added in the editor with no code panel shows a simple placeholder. */}
        {visible.map((tb) => (
          <div key={tb.id} style={{ height: '100%', display: tab === tb.id ? 'block' : 'none' }}>
            {PAGES[tb.id] || (
              <div style={{ padding: 40, color: 'var(--text-muted)', fontSize: 'var(--fs-small, 12px)' }}>
                {tb.label || tb.id}
              </div>
            )}
          </div>
        ))}
      </AppShell>

      {/* transient status toasts — top-right, just under the account button */}
      <div style={{ position: 'fixed', top: 58, right: 16, zIndex: 1000, display: 'flex', flexDirection: 'column',
        gap: 8, alignItems: 'flex-end', pointerEvents: 'none' }}>
        {toasts.map((tst) => {
          const err = tst.level === 'error'
          return (
            <div key={tst.id} style={{ pointerEvents: 'auto', maxWidth: 360, display: 'flex', alignItems: 'flex-start', gap: 8,
              background: 'var(--surface, #fff)', color: err ? '#dc2626' : 'var(--text-primary, #1a1a1a)',
              border: err ? '1.5px solid #dc2626' : '1px solid var(--border-default, #ddd)',
              borderLeft: err ? '5px solid #dc2626' : '1px solid var(--border-default, #ddd)', borderRadius: 10,
              padding: err ? '11px 15px' : '9px 13px', fontWeight: err ? 600 : 400,
              boxShadow: err ? '0 8px 28px rgba(220,38,38,0.34)' : '0 6px 20px rgba(0,0,0,0.16)',
              fontSize: 13, lineHeight: 1.4,
              animation: err ? 'nptoastin .16s ease-out, nptoastshake .34s ease-out .16s' : 'nptoastin .16s ease-out' }}>
              {err && <span style={{ flex: 'none', fontSize: 15, lineHeight: 1.25 }}>⚠️</span>}
              <span>{tst.text}</span>
            </div>
          )
        })}
      </div>
      <style>{'@keyframes nptoastin{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}'
        + '@keyframes nptoastshake{0%,100%{transform:translateX(0)}20%{transform:translateX(-5px)}40%{transform:translateX(5px)}60%{transform:translateX(-3px)}80%{transform:translateX(2px)}}'}</style>
    </>
  )
}
